<!DOCTYPE html>
<html lang="en">
<head>
 <meta charset="utf-8">
 <meta name="viewport" content="width=device-width, initial-scale=1">
 <title>Incursa UI Kit - Web Components</title>
 <script>
 (() => {
 const storageKey = "inc-theme-mode";
 const resolveTheme = (mode) => mode === "dark" || mode === "light"
 ? mode
 : (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
 let mode = "system";

 try {
 const storedMode = window.localStorage.getItem(storageKey);

 if (storedMode === "light" || storedMode === "dark" || storedMode === "system") {
 mode = storedMode;
 }
 } catch {
 // Ignore storage restrictions before the component runtime bootstraps.
 }

 document.documentElement.setAttribute("data-inc-theme-mode", mode);
 document.documentElement.setAttribute("data-bs-theme", resolveTheme(mode));
 document.documentElement.style.colorScheme = resolveTheme(mode);
 })();
 </script>
 <link rel="stylesheet" href="./dist/inc-design-language.css">
 <link rel="stylesheet" href="./showcase.css">
 <style>
 :root {
 --wc-showcase-radius: var(--demo-surface-radius);
 }

 body {
 color: var(--inc-text-primary);
 }

 .wc-showcase {
 display: grid;
 gap: 1.25rem;
 }

 .wc-hero {
 display: grid;
 gap: 1rem;
 align-items: start;
 }

 .wc-grid {
 display: grid;
 gap: 1rem;
 align-items: start;
 }

 .wc-grid--2 {
 grid-template-columns: repeat(2, minmax(0, 1fr));
 }

 .wc-grid--3 {
 grid-template-columns: repeat(3, minmax(0, 1fr));
 }

 .wc-note {
 color: var(--inc-text-muted);
 margin: 0;
 }

 .wc-code {
 background: var(--demo-surface-muted);
 border: 1px solid var(--demo-border);
 border-radius: var(--wc-showcase-radius);
 padding: 1rem;
 overflow: auto;
 color: var(--inc-text-primary);
 }

 .demo-compare__panel {
 border-radius: var(--wc-showcase-radius);
 }

 .demo-muted-panel,
 .demo-preview,
 .demo-surface-muted {
 border-radius: var(--wc-showcase-radius);
 }

 .demo-code {
 border-radius: var(--wc-showcase-radius);
 }

 .demo-swatch {
 border-radius: var(--wc-showcase-radius);
 }

 .wc-tabs {
 display: grid;
 gap: 0.75rem;
 }

 .wc-tabs [slot="tab"] {
 appearance: none;
 border: 1px solid var(--inc-border-subtle);
 background: var(--inc-surface-secondary);
 color: var(--inc-text-secondary);
 border-radius: 0.5rem;
 padding: 0.65rem 0.9rem;
 }

 .wc-tabs [slot="tab"][aria-selected="true"] {
 background: var(--inc-surface-primary);
 color: var(--inc-text-primary);
 font-weight: 600;
 }

 .wc-tabs [slot="panel"][hidden] {
 display: none !important;
 }

 .wc-actions {
 display: flex;
 flex-wrap: wrap;
 gap: 0.75rem;
 align-items: flex-start;
 }

 #wc-navbar {
 flex-wrap: nowrap;
 }

 #wc-navbar .inc-navbar__nav {
 flex: 1 1 auto;
 min-width: 0;
 overflow-x: auto;
 overflow-y: hidden;
 scrollbar-width: none;
 }

 #wc-navbar .inc-navbar__nav::-webkit-scrollbar {
 display: none;
 }

 #wc-navbar .inc-navbar__nav .nav-link,
 #wc-navbar .inc-navbar__nav .inc-nav-link {
 flex: 0 0 auto;
 white-space: nowrap;
 }

 @media (max-width: 900px) {
 .wc-grid--2,
 .wc-grid--3 {
 grid-template-columns: 1fr;
 }
 }
 </style>
</head>
<body>
 <inc-app-shell id="wc-shell" class="inc-app-shell" variant="demo">
 <header slot="header" class="inc-app-shell__header">
 <inc-navbar id="wc-navbar" app breakpoint="lg">
 <a slot="brand" class="inc-navbar__brand" href="#wc-home">Incursa</a>
 <div slot="nav" class="inc-navbar__nav">
 <a class="nav-link" href="./index.html">Examples</a>
 <a class="nav-link" href="./demo.html">Dashboard</a>
 <a class="nav-link" href="./work-queue.html">Work Queue</a>
 <a class="nav-link" href="./record-detail.html">Record Detail</a>
 <a class="nav-link" href="./native-patterns.html">Native Patterns</a>
 <a class="nav-link" href="./overlay-workflows.html">Overlays</a>
 <a class="nav-link" href="./states.html">States</a>
 <a class="nav-link" href="./forms-and-validation.html">Forms</a>
 <a class="nav-link" href="./data-grid-advanced.html">Data Grid</a>
 <a class="nav-link active" href="./web-components.html">Web Components</a>
 <a class="nav-link" href="./reference.html">Reference</a>
 </div>
 <div slot="utilities" class="inc-navbar__utilities">
 <inc-theme-switcher id="wc-theme-switcher" variant="navbar" block label="Theme" menu-label="Theme menu" heading="Choose appearance"></inc-theme-switcher>
 <details class="inc-native-menu inc-native-menu--navbar">
 <summary class="inc-native-menu__summary">
 <span class="inc-user-menu__avatar">SM</span>
 <span class="inc-user-menu__meta">
 <span class="inc-user-menu__name">Sam McAravey</span>
 <span class="inc-user-menu__detail">Administrator</span>
 </span>
 </summary>
 <div class="inc-native-menu__panel">
 <div class="inc-native-menu__header">Signed in as Sam McAravey</div>
 <a class="inc-native-menu__item" href="#">Profile</a>
 <a class="inc-native-menu__item" href="#">Preferences</a>
 <a class="inc-native-menu__item" href="#">Sign out</a>
 </div>
 </details>
 </div>
 <div slot="collapse" class="inc-navbar__collapse">
 <button id="wc-navbar-toggle" class="inc-navbar__toggler inc-btn inc-btn--outline-secondary inc-btn--sm" type="button" data-inc-navbar-toggle>
 Menu
 </button>
 </div>
 </inc-navbar>
 </header>

 <main slot="main" class="inc-app-shell__main">
 <div class="inc-section-container">
 <inc-page id="wc-page" class="inc-page">
 <div slot="breadcrumbs" class="inc-page__breadcrumbs">
 <ol class="inc-breadcrumb">
 <li class="inc-breadcrumb__item"><a href="#wc-home">Examples</a></li>
 <li class="inc-breadcrumb__item active"><span>Web Components</span></li>
 </ol>
 </div>

 <inc-page-header slot="header" id="wc-header" class="inc-page-header">
 <div slot="title" class="wc-hero">
 <p class="demo-eyebrow">Optional Layer</p>
 <h1 class="inc-heading inc-heading--h1">Browser-native components that stay inside the same CSS kit.</h1>
 <p class="inc-text inc-text--regular inc-text--muted">Use the class-based UI kit when you only need the language. Use the Web Component layer when you want declarative HTML, attributes, slots, DOM events, and the same design vocabulary from plain browser markup.</p>
 </div>
 <div slot="actions" class="wc-actions">
 <a class="inc-btn inc-btn--secondary inc-btn--sm" href="./README.md">Read the package docs</a>
 <a class="inc-btn inc-btn--primary inc-btn--sm" href="./src/web-components/README.md">Read the maintainer notes</a>
 </div>
 </inc-page-header>

 <section slot="body" id="wc-home" class="wc-showcase">
 <inc-card class="inc-card inc-card--elevated" elevated>
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">Load the entrypoints</h2>
 </div>
 <div slot="body" class="wc-grid wc-grid--2">
 <div>
 <p class="inc-text inc-text--regular">The package export is `@incursa/ui-kit/web-components`. Pair it with `@incursa/ui-kit/web-components/style.css` for the default look, then import the runtime once to register the shipped elements.</p>
 <pre class="wc-code"><code>&lt;link rel="stylesheet" href="/node_modules/@incursa/ui-kit/web-components/style.css"&gt;
&lt;script type="module"&gt;
 import "@incursa/ui-kit/web-components";
&lt;/script&gt;</code></pre>
 </div>
 <div>
 <p class="wc-note">The v1 layer covers layouts, navbar/tabs/user-menu, field/input-group/choice-group/readonly-field/validation-summary, state/live-region/auto-refresh/theme-switcher, button/button-group/button-toolbar/close-button, alert/empty-state/list-group/key-value hosts, badge/spinner atoms, sparkline trends, and disclosure/dialog/drawer.</p>
 <p class="wc-note">Tables, filters, bulk workflows, files, utilities, and most other presentation-only atoms stay CSS-first for now. Sparklines are promoted because dense metric tables need a reusable accessible trend primitive.</p>
 </div>
 </div>
 </inc-card>

 <section id="wc-comparison" class="demo-compare demo-compare--2">
 <article class="demo-compare__panel">
 <p class="demo-eyebrow">Plain HTML equivalent</p>
 <h2 class="demo-compare__title inc-heading inc-heading--h3">Explicit class wiring</h2>
 <p class="demo-compare__copy">This is the CSS-first version of the same screen shape. It works, but the structure is louder because every wrapper is spelled out by hand.</p>
 <pre class="demo-code"><code>&lt;section class="inc-card"&gt;
 &lt;div class="inc-card__header"&gt;
 &lt;h2 class="inc-card__title"&gt;Queue summary&lt;/h2&gt;
 &lt;/div&gt;
 &lt;div class="inc-card__body"&gt;
 &lt;table class="inc-table inc-table--sm inc-table--data-table"&gt;
 &lt;thead&gt;...&lt;/thead&gt;
 &lt;tbody&gt;...&lt;/tbody&gt;
 &lt;/table&gt;
 &lt;/div&gt;
&lt;/section&gt;</code></pre>
 </article>

 <article class="demo-compare__panel">
 <p class="demo-eyebrow">Web Components equivalent</p>
 <h2 class="demo-compare__title inc-heading inc-heading--h3">Shorter markup, same result</h2>
 <p class="demo-compare__copy">The Web Component layer lets the browser own the semantics while the slots keep the layout contract obvious and reusable.</p>
 <pre class="demo-code"><code>&lt;inc-card elevated&gt;
 &lt;div slot="header" class="inc-card__header"&gt;
 &lt;h2 class="inc-card__title"&gt;Queue summary&lt;/h2&gt;
 &lt;/div&gt;
 &lt;div slot="body"&gt;
 &lt;table class="inc-table inc-table--sm inc-table--data-table"&gt;
 &lt;thead&gt;...&lt;/thead&gt;
 &lt;tbody&gt;...&lt;/tbody&gt;
 &lt;/table&gt;
 &lt;/div&gt;
&lt;/inc-card&gt;</code></pre>
 </article>
 </section>

 <inc-card id="wc-shell-metrics" class="inc-card">
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">Shell, navigation, and metrics</h2>
 </div>
 <div slot="body" class="wc-grid wc-grid--2">
 <inc-summary-overview class="inc-summary-overview inc-summary-overview--3-col" columns="3">
 <inc-summary-block class="inc-summary-block">
 <div slot="header">Queue</div>
 <div slot="body"><strong>124</strong></div>
 <div slot="footer">Pending review</div>
 </inc-summary-block>
 <inc-summary-block class="inc-summary-block inc-summary-block--tone-warning" tone="warning">
 <div slot="header">Risks</div>
 <div slot="body"><strong>7</strong></div>
 <div slot="footer">Needs attention</div>
 </inc-summary-block>
 <inc-summary-block class="inc-summary-block inc-summary-block--tone-positive" tone="positive">
 <div slot="header">Saved</div>
 <div slot="body"><strong>$18.2k</strong></div>
 <div slot="footer">This week</div>
 </inc-summary-block>
 </inc-summary-overview>
 <inc-tabs id="wc-tabs" orientation="horizontal" activation="auto" selected="wc-tab-review">
 <button slot="tab" id="wc-tab-review" type="button" class="inc-tab" aria-controls="wc-panel-review">Needs Review</button>
 <button slot="tab" id="wc-tab-ready" type="button" class="inc-tab" aria-controls="wc-panel-ready">Ready To Approve</button>
 <button slot="tab" id="wc-tab-exported" type="button" class="inc-tab" aria-controls="wc-panel-exported">Recently Exported</button>
 <section slot="panel" id="wc-panel-review" class="inc-tab-pane">Review queue content.</section>
 <section slot="panel" id="wc-panel-ready" class="inc-tab-pane">Ready-to-approve content.</section>
 <section slot="panel" id="wc-panel-exported" class="inc-tab-pane">Recently exported content.</section>
 </inc-tabs>
 </div>
 </inc-card>

 <inc-card id="wc-atomic-controls" class="inc-card">
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">Atomic controls with stable defaults</h2>
 </div>
 <div slot="body" class="wc-grid wc-grid--2">
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Badge hosts standardize tone and pill styling without making you memorize the class suffix chain.</p>
 <div class="wc-actions">
 <inc-badge id="wc-badge-default">Draft</inc-badge>
 <inc-badge id="wc-badge-success" tone="success" pill>Approved</inc-badge>
 <inc-badge id="wc-badge-warning" tone="warning">Pending</inc-badge>
 </div>
 </div>
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Spinner hosts standardize loading variants and accessible labels.</p>
 <div class="wc-actions">
 <inc-spinner id="wc-spinner-border" label="Loading queue"></inc-spinner>
 <inc-spinner id="wc-spinner-grow" variant="grow" tone="primary" size="sm" label="Refreshing"></inc-spinner>
 </div>
 </div>
 </div>
 </inc-card>

 <inc-card id="wc-action-shells" class="inc-card">
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">Buttons, alerts, and empty states</h2>
 </div>
 <div slot="body" class="wc-grid wc-grid--2">
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Button hosts wrap native controls and standardize tone, size, and loading defaults.</p>
 <div class="wc-actions">
 <inc-button id="wc-button-primary" tone="primary">Approve</inc-button>
 <inc-button id="wc-button-secondary" tone="secondary" size="sm">Save Draft</inc-button>
 <inc-button id="wc-button-loading" tone="outline-secondary" loading label="Saving approval">Saving</inc-button>
 </div>
 <div class="wc-actions">
 <inc-button id="wc-button-inline-loading" tone="primary" size="sm" label="Publishing approval">
 <span class="inc-spinner inc-spinner--border inc-spinner--border--sm" aria-hidden="true"></span>
 <span>Publishing</span>
 </inc-button>
 <inc-button id="wc-button-inline-loading-secondary" variant="outline-secondary" size="sm" label="Refreshing queue">
 <span class="inc-spinner inc-spinner--border inc-spinner--border--sm" aria-hidden="true"></span>
 <span>Refreshing</span>
 </inc-button>
 </div>
 <inc-button-group id="wc-button-group" size="sm" label="Queue mode">
 <inc-button tone="secondary">Light</inc-button>
 <inc-button tone="secondary">Dark</inc-button>
 <inc-button tone="secondary">System</inc-button>
 </inc-button-group>
 <inc-button-toolbar id="wc-button-toolbar" label="Quick actions">
 <inc-button tone="secondary" size="sm">Refresh</inc-button>
 <inc-button tone="primary" size="sm">Export</inc-button>
 <inc-close-button id="wc-close-button" label="Dismiss panel"></inc-close-button>
 </inc-button-toolbar>
 </div>
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Alerts and empty-state shells keep the repeated runtime scaffolding declarative.</p>
 <inc-alert id="wc-alert-success" tone="success" dismissible dismiss-label="Dismiss success" timeout="5000">Success alert text.</inc-alert>
 <inc-alert id="wc-alert-info" tone="info">Information alert text.</inc-alert>
 <inc-alert id="wc-alert-warning" tone="warning" dismissible dismiss-label="Dismiss warning">Warning alert text.</inc-alert>
 <inc-empty-state id="wc-empty-state" icon="empty">
 <h3 class="inc-heading inc-heading--h3">No saved views</h3>
 <p class="inc-text inc-text--regular inc-text--muted">Create a named filter set so your operators can reuse it across screens.</p>
 <div slot="actions" class="wc-actions">
 <inc-button tone="secondary" size="sm">Dismiss</inc-button>
 <inc-button tone="primary" size="sm">Create View</inc-button>
 </div>
 </inc-empty-state>
 </div>
 </div>
 </inc-card>

 <inc-card id="wc-collection-shells" class="inc-card">
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">List groups and key values</h2>
 </div>
 <div slot="body" class="wc-grid wc-grid--2">
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">List-group hosts standardize repeated action-row markup without changing list semantics.</p>
 <inc-list-group id="wc-list-group" label="Saved views">
 <a slot="item" href="#">Needs review</a>
 <a slot="item" href="#">March closeout</a>
 <a slot="item" href="#">Projects missing billing period</a>
 </inc-list-group>
 <inc-list-group id="wc-numbered-list-group" numbered label="Review steps">
 <li slot="item">First review pass</li>
 <li slot="item">Secondary approval</li>
 <li slot="item">Final export</li>
 </inc-list-group>
 </div>
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Key-value hosts standardize the repeated description-list pair pattern.</p>
 <inc-key-value-grid id="wc-key-value-grid" columns="2">
 <inc-key-value id="wc-key-value-record" label="Record Id" value="AP-2026-00142" meta="Synced 8:13 AM" card></inc-key-value>
 <inc-key-value id="wc-key-value-amount" label="Current request" value="$18,240.22" card></inc-key-value>
 </inc-key-value-grid>
 </div>
 </div>
 </inc-card>

 <inc-card id="wc-sparkline-trends" class="inc-card">
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">Sparkline trend evidence</h2>
 </div>
 <div slot="body" class="inc-stack inc-stack--gap-md">
 <div class="wc-grid wc-grid--2">
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Static pages can pass simple numeric values. Timestamped benchmark history can use the `points` JSON attribute or the `points` property.</p>
 <div class="wc-actions">
 <inc-sparkline values="12,15,14,20,18" width="120" height="28" aria-label="Five point revenue trend"></inc-sparkline>
 <inc-sparkline points='[{"x":"2026-06-01","y":1200},{"x":"2026-06-02","y":1350},{"x":"2026-06-03","y":1280},{"x":"2026-06-04","y":1480}]' width="120" height="28" variant="area" tone="accent" curve="monotone" aria-label="Timestamped benchmark history"></inc-sparkline>
 </div>
 </div>
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">Markers and reference lines remain decorative support. The surrounding cell should still show the current value and delta.</p>
 <div class="wc-actions">
 <inc-sparkline values="5120,5400,5310,5600,5510" height="28" width="120" tone="accent" show-last-marker aria-label="Recent requests per second trend for Incursa HTTP/3 on HTTP plaintext"></inc-sparkline>
 <inc-sparkline values="-3,-1,2,1,4" height="28" width="120" tone="positive" reference-value="0" show-min-max aria-label="Mixed positive and negative delta trend"></inc-sparkline>
 </div>
 </div>
 </div>
 <div class="wc-actions">
 <inc-sparkline values="4,5,7,8,10" height="24" width="96" tone="positive" aria-label="Positive trend"></inc-sparkline>
 <inc-sparkline values="10,8,7,5,4" height="24" width="96" tone="negative" aria-label="Negative trend"></inc-sparkline>
 <inc-sparkline values="7,7,7,7" height="24" width="96" tone="muted" curve="step" show-last-marker aria-label="Flat muted trend"></inc-sparkline>
 <inc-sparkline values="bad,data" height="24" width="96" empty-label="No data" aria-label="Empty sparkline example"></inc-sparkline>
 </div>
 <div class="inc-table-responsive">
 <table class="inc-table inc-table--sm inc-table--data-table">
 <thead>
 <tr>
 <th class="inc-table__header">Benchmark</th>
 <th class="inc-table__header inc-table__header--right">Current</th>
 <th class="inc-table__header">History</th>
 <th class="inc-table__header">Delta</th>
 </tr>
 </thead>
 <tbody>
 <tr>
 <td class="inc-table__cell">HTTP/3 plaintext</td>
 <td class="inc-table__cell inc-table__cell--numeric">5,510 rps</td>
 <td class="inc-table__cell">
 <inc-sparkline values="5120,5400,5310,5600,5510" height="28" width="120" tone="accent" show-last-marker aria-label="Recent requests per second trend for Incursa HTTP/3 on HTTP plaintext"></inc-sparkline>
 </td>
 <td class="inc-table__cell"><span class="inc-badge inc-badge--success inc-badge--pill">+3.1%</span></td>
 </tr>
 <tr>
 <td class="inc-table__cell">QPACK decode</td>
 <td class="inc-table__cell inc-table__cell--numeric">1.42 ms</td>
 <td class="inc-table__cell">
 <inc-sparkline values="1.6,1.5,1.45,1.47,1.42" height="28" width="120" tone="positive" show-min-max aria-label="Recent QPACK decode latency trend"></inc-sparkline>
 </td>
 <td class="inc-table__cell"><span class="inc-badge inc-badge--success inc-badge--pill">Best</span></td>
 </tr>
 </tbody>
 </table>
 </div>
 </div>
 </inc-card>

 <inc-card id="wc-data-presentation" class="inc-card">
 <div slot="header" class="inc-card__header">
 <h2 class="inc-card__title">Tables, colors, and low-level presentation stay CSS-first</h2>
 </div>
 <div slot="body" class="wc-grid wc-grid--2">
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">The Web Component layer does not replace the table styling language. It reuses the same class-based table system where that is still the right contract.</p>
 <table class="inc-table inc-table--sm inc-table--data-table">
 <thead>
 <tr>
 <th class="inc-table__header">Project</th>
 <th class="inc-table__header">Period</th>
 <th class="inc-table__header inc-table__header--right">Amount</th>
 <th class="inc-table__header">Status</th>
 </tr>
 </thead>
 <tbody>
 <tr>
 <td class="inc-table__cell inc-table__cell--data">AP-2026-00142</td>
 <td class="inc-table__cell">March 2026</td>
 <td class="inc-table__cell inc-table__cell--numeric">$18,240.22</td>
 <td class="inc-table__cell"><span class="inc-badge inc-badge--success inc-badge--pill">Approved</span></td>
 </tr>
 <tr>
 <td class="inc-table__cell inc-table__cell--data">AP-2026-00144</td>
 <td class="inc-table__cell">March 2026</td>
 <td class="inc-table__cell inc-table__cell--numeric">$4,992.00</td>
 <td class="inc-table__cell"><span class="inc-badge inc-badge--warning inc-badge--pill">Pending</span></td>
 </tr>
 </tbody>
 </table>
 </div>
 <div class="inc-stack inc-stack--gap-sm">
 <p class="wc-note">The color story and compact action buttons still match the CSS-first kit exactly.</p>
 <div class="demo-swatch-grid">
 <div class="demo-swatch demo-swatch--on-dark" style="background: var(--bs-primary); border-color: transparent;">
 <span class="demo-swatch__token">Primary</span>
 <span class="demo-swatch__name">Action color</span>
 <span class="demo-swatch__value">var(--bs-primary)</span>
 </div>
 <div class="demo-swatch demo-swatch--warning" style="background: rgb(198, 136, 0); border-color: transparent;">
 <span class="demo-swatch__token">Warning</span>
 <span class="demo-swatch__name">Attention state</span>
 <span class="demo-swatch__value">var(--bs-warning)</span>
 </div>
 <div class="demo-swatch demo-swatch--on-dark" style="background: var(--bs-danger); border-color: transparent;">
 <span class="demo-swatch__token">Danger</span>
 <span class="demo-swatch__name">High-risk state</span>
 <span class="demo-swatch__value">var(--bs-danger)</span>
 </div>
 <div class="demo-swatch demo-swatch--surface" style="background: var(--inc-surface-secondary);">
 <span class="demo-swatch__token">Surface</span>
 <span class="demo-swatch__name">Neutral panel</span>
 <span class="demo-swatch__value">var(--inc-surface-secondary)</span>
 </div>
 </div>
 <div class="wc-actions">
 <button class="inc-btn inc-btn--secondary inc-btn--sm" type="button">Secondary</button>
