}

.modal-backdrop {
 display: none;
 z-index: $inc-z-index-modal-backdrop;
}

.modal-backdrop.show ~ .modal-backdrop.show {
 z-index: $inc-z-index-modal-backdrop + 10;
}

.modal.show ~ .modal.show {
 z-index: $inc-z-index-modal + 10;
}

.inc-offcanvas {
 position: fixed;
 z-index: $inc-z-index-modal;
 display: flex;
 flex-direction: column;
 max-width: 100%;
 background: var(--inc-surface-primary);
 color: var(--inc-text-primary);
 visibility: hidden;
 box-shadow: 0 1.25rem 2.5rem rgba(var(--inc-surface-strong-rgb), 0.18);
 transition: transform 0.25s ease, visibility 0.25s ease;

 &.is-open {
