.inc-offcanvas-title {
 margin: 0;
 font-size: 1.125rem;
 font-weight: 600;
 line-height: 1.2;
}

.inc-offcanvas-body {
 flex: 1 1 auto;
 padding: 1.25rem;
 overflow-y: auto;
}

body.inc-offcanvas-open {
 overflow: hidden;
}

