 background-size: 200% 100%;
 animation: inc-skeleton-shimmer 1.5s linear infinite;

 &--title {
 height: 1rem;
 width: 40%;
 border-radius: 0.375rem;
 }

 &--text {
 height: 0.75rem;
 width: 100%;
 }

