 flex-direction: column;
 gap: 0.125rem;
}

.inc-table__bundle-title {
 font-weight: 600;
 white-space: nowrap;
}

.inc-table__bundle-hint {
 color: var(--inc-text-muted);
 font-size: 0.75rem;
 line-height: 1.3;
 white-space: normal;
}

.inc-table-container {
 position: relative;
 overflow: visible;
}

.inc-table-responsive {
 @extend .table-responsive;
 -webkit-overflow-scrolling: touch;

 &::-webkit-scrollbar {
 height: 8px;
 }

 &::-webkit-scrollbar-track {
 background: var(--bs-gray-100);
 border-radius: 4px;
 }

 &::-webkit-scrollbar-thumb {
 background: var(--bs-gray-400);
 border-radius: 4px;

 &:hover {
 background: var(--bs-gray-500);
 }
 }

 &--sm {
 @extend .table-responsive-sm;
 }

 &--md {
 @extend .table-responsive-md;
 }

 &--lg {
 @extend .table-responsive-lg;
 }

 &--xl {
 @extend .table-responsive-xl;
 }

 &--xxl {
 @extend .table-responsive-xxl;
 }

 &__caption {
 @extend .caption-top;
 }

 &__footer {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: 0.75rem;
 background-color: var(--inc-surface-secondary);
 border-top: 1px solid var(--inc-border-default);
 }

 &__pagination {
 margin: 0;
 }
}

.inc-header-body,
.inc-header-body__body,
.inc-table tbody tr td,
.inc-table tbody tr td:last-child {
 overflow: visible;
}

.inc-table tbody tr td:last-child {
 position: relative;
}

// -----------------------------------------------------------------------------
// Overlay helpers
// -----------------------------------------------------------------------------

.inc-modal {
 position: fixed;
 inset: 0;
 z-index: $inc-z-index-modal;
 display: flex;
 align-items: center;
 justify-content: center;
 pointer-events: none;
 opacity: 0;
 visibility: hidden;
 transition: opacity 0.2s ease, visibility 0.2s ease;

 &[hidden] {
 display: none !important;
 }

 &.is-open {
 pointer-events: auto;
 opacity: 1;
 visibility: visible;
 }

 &[style*="display: flex"],
 &[style*="display:flex"] {
 pointer-events: auto;
 }

 &__backdrop {
 position: absolute;
 inset: 0;
 background-color: rgba(0, 0, 0, 0.5);
 z-index: 1;
 display: flex;
 align-items: center;
 justify-content: center;
 }

 &__dialog {
 background: var(--inc-surface-primary);
 border-radius: $inc-radius-md;
 max-width: 31.25rem;
 width: 90%;
 max-height: 90vh;
 overflow-y: auto;
 box-shadow: 0 10px 25px rgba(var(--inc-surface-strong-rgb), 0.5);
 position: relative;
 z-index: 2;

 &--sm {
 max-width: 18.75rem;
 }

 &--lg {
 max-width: 50rem;
 }

 &--xl {
 max-width: 71.25rem;
 }

 &--fullscreen {
 max-width: 100%;
 width: 100%;
 height: 100%;
 max-height: 100%;
 margin: 0;
 border-radius: 0;
 }
 }

 &__content {
 padding: 0;
 }

 &__header {
 padding: 1rem 1.5rem;
 border-bottom: 1px solid var(--inc-border-subtle);
 display: flex;
 align-items: center;
 justify-content: space-between;
 }

 &__title {
 margin: 0;
 font-size: 1.25rem;
 font-weight: 600;
 }

 &__body {
 padding: 1.5rem;
 }

 &__close {
 background: none;
 border: none;
 font-size: 1.5rem;
 cursor: pointer;
 padding: 0;
 width: 2rem;
 height: 2rem;
 display: flex;
 align-items: center;
 justify-content: center;

 &:hover {
 opacity: 0.7;
 }
 }

 &__footer {
 padding: 1rem 1.5rem;
 border-top: 1px solid var(--inc-border-subtle);
 display: flex;
 gap: 1rem;
 justify-content: flex-end;
 }
}

body.inc-modal-open {
 overflow: hidden;
}

.inc-loading {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 min-height: 12.5rem;
}

.modal {
 z-index: $inc-z-index-modal;
}

.modal-backdrop {
 display: none;
 z-index: $inc-z-index-modal-backdrop;
}

.modal-backdrop.show ~ .modal-backdrop.show {
 z-index: $inc-z-index-modal-backdrop + 10;
}

.modal.show ~ .modal.show {
 z-index: $inc-z-index-modal + 10;
}

.inc-offcanvas {
 position: fixed;
 z-index: $inc-z-index-modal;
 display: flex;
 flex-direction: column;
 max-width: 100%;
 background: var(--inc-surface-primary);
 color: var(--inc-text-primary);
 visibility: hidden;
 box-shadow: 0 1.25rem 2.5rem rgba(var(--inc-surface-strong-rgb), 0.18);
 transition: transform 0.25s ease, visibility 0.25s ease;

 &.is-open {
 visibility: visible;
 }
}

.inc-offcanvas-start,
.inc-offcanvas-end {
 top: 0;
 bottom: 0;
 width: min(34rem, 92vw);
}

.inc-offcanvas-start {
 left: 0;
 transform: translateX(-100%);

 &.is-open {
 transform: translateX(0);
 }
}

.inc-offcanvas-end {
 right: 0;
 transform: translateX(100%);

 &.is-open {
 transform: translateX(0);
 }
}

.inc-offcanvas-top,
.inc-offcanvas-bottom {
 left: 0;
 right: 0;
 height: min(24rem, 85vh);
}

.inc-offcanvas-top {
 top: 0;
 transform: translateY(-100%);

 &.is-open {
 transform: translateY(0);
 }
}

.inc-offcanvas-bottom {
 bottom: 0;
 transform: translateY(100%);

 &.is-open {
 transform: translateY(0);
 }
}

.inc-offcanvas-backdrop {
 position: fixed;
 inset: 0;
 z-index: $inc-z-index-modal-backdrop;
 background: rgba(15, 20, 34, 0.46);
 opacity: 0;
 pointer-events: none;
 transition: opacity 0.2s ease;

 &.is-open {
 opacity: 1;
 pointer-events: auto;
 }
}

.inc-offcanvas-header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 1rem;
 padding: 1rem 1.25rem;
 border-bottom: 1px solid var(--inc-border-subtle);
}

.inc-offcanvas-title {
 margin: 0;
 font-size: 1.125rem;
 font-weight: 600;
 line-height: 1.2;
}

.inc-offcanvas-body {
 flex: 1 1 auto;
 padding: 1.25rem;
 overflow-y: auto;
}

body.inc-offcanvas-open {
 overflow: hidden;
}

// -----------------------------------------------------------------------------
// B2B Workflow Additions
// -----------------------------------------------------------------------------

@keyframes inc-skeleton-shimmer {
