 width: 1.375rem;
 height: 1.375rem;
 }
 }

 &__title {
 margin: 0;
 font-size: 1.125rem;
 font-weight: 600;
 }

 &__body {
 color: var(--inc-text-muted);
 font-size: 0.875rem;
 line-height: 1.6;
 margin: 0;
 }

 &__actions {
 display: flex;
 flex-wrap: wrap;
 gap: 0.75rem;
