 gap: 1rem 1.5rem;
}

.inc-key-value {
 display: flex;
 flex-direction: column;
 gap: 0.25rem;
 min-width: 0;
 margin: 0;

 &--card {
 padding: 0.875rem 1rem;
 border: 1px solid var(--inc-border-subtle);
 border-radius: $inc-radius-md;
 background: var(--inc-surface-primary);
 }

 &__label {
