 width: 7.5rem;
 }
}

.inc-loading-dots {
 display: inline-flex;
 gap: 0.375rem;
 align-items: center;

 span {
 width: 0.5rem;
 height: 0.5rem;
 border-radius: 999px;
 background: $primary;
 opacity: 0.3;
 animation: inc-loading-pulse 0.9s ease-in-out infinite alternate;

 &:nth-child(2) {
 animation-delay: 0.2s;
 }

 &:nth-child(3) {
 animation-delay: 0.4s;
 }
 }
}

@keyframes inc-loading-pulse {
 to {
 opacity: 1;
 transform: translateY(-0.125rem);
 }
}

.inc-btn.is-loading {
 position: relative;
 pointer-events: none;
 text-indent: -9999px;
 overflow: hidden;
 white-space: nowrap;

 &:has(> .inc-spinner)::after,
 &:has(> .inc-loading-dots)::after {
 display: none;
 }

 > .inc-spinner {
 position: absolute;
 inset: 50% auto auto 50%;
 margin: -0.5rem 0 0 -0.5rem;
 transform: none;
 }

 > .inc-loading-dots {
 position: absolute;
 inset: 50% auto auto 50%;
 transform: translate(-50%, -50%);
 }

 &::after {
 content: "";
 position: absolute;
 inset: 50% auto auto 50%;
 width: 1rem;
 height: 1rem;
 margin: -0.5rem 0 0 -0.5rem;
 border-radius: 999px;
 border: 0.125rem solid currentColor;
 border-right-color: transparent;
 animation: inc-loading-spin 0.8s linear infinite;
 }
}

