 justify-content: flex-end;
 }

 @media (max-width: 767.98px) {
 flex-direction: column;
 align-items: stretch;

 &__actions {
 justify-content: flex-start;
 }
 }
}

.inc-table {
 &--sticky-header {
 thead th {
 position: sticky;
 top: 0;
 z-index: 2;
 }
 }

 &__cell,
 &__header {
 &--sticky {
 position: sticky;
 left: 0;
 z-index: 1;
 }
 }

 &__header--sticky {
 z-index: 3;
 }

 &__row {
 &--selected > * {
 background: rgba(var(--bs-primary-rgb), 0.08) !important;
 }

 &--warning > * {
 background: rgba(var(--bs-warning-rgb), 0.08) !important;
 }

 &--danger > * {
 background: rgba(var(--bs-danger-rgb), 0.06) !important;
 }

 &--locked > * {
 background: var(--inc-surface-muted) !important;
 color: var(--inc-text-muted);
 }
 }
}

.inc-table-responsive--sticky {
 max-height: 26rem;
 overflow: auto;
}

.inc-timeline {
 display: flex;
 flex-direction: column;
 gap: 1rem;

 &__item {
 display: grid;
 grid-template-columns: 1rem minmax(0, 1fr);
 gap: 1rem;
 align-items: start;
 }

 &__rail {
 position: relative;
 display: flex;
 justify-content: center;
 min-height: 100%;

 &::before {
 content: "";
 position: absolute;
 top: 0;
 bottom: -1rem;
 width: 0.125rem;
 background: var(--inc-border-subtle);
 }
 }

 &__item:last-child .inc-timeline__rail::before {
 bottom: 0;
 }

 &__dot {
 width: 0.75rem;
 height: 0.75rem;
 border-radius: 999px;
 background: $primary;
 box-shadow: 0 0 0 0.1875rem var(--inc-surface-primary);
 position: relative;
 z-index: 1;

 &--warning {
 background: $warning;
 }

 &--danger {
 background: $danger;
 }

 &--success {
 background: $success;
 }
 }

 &__content {
 display: flex;
 flex-direction: column;
 gap: 0.5rem;
 padding: 0.875rem 1rem;
 border: 1px solid var(--inc-border-subtle);
 border-radius: $inc-radius-md;
 background: var(--inc-surface-primary);
 }

 &__header,
 &__meta {
 display: flex;
 flex-wrap: wrap;
 gap: 0.5rem 0.75rem;
 align-items: center;
 }

 &__title {
 margin: 0;
 font-size: 0.875rem;
 font-weight: 600;
 }

 &__meta {
 color: var(--inc-text-muted);
 font-size: 0.75rem;
 }

 &__body {
 margin: 0;
 color: var(--inc-text-primary);
 font-size: 0.8125rem;
 line-height: 1.6;
 }
}

.inc-file-dropzone {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 1rem;
 padding: 1rem 1.125rem;
 border: 1.5px dashed $inc-border-strong;
 border-radius: $inc-radius-md;
 background: linear-gradient(180deg, var(--inc-surface-secondary), var(--inc-surface-primary));
 transition: border-color 160ms ease, background 160ms ease, box-shadow 160ms ease;

 &[role="button"] {
 cursor: pointer;
 }

 &__content {
 display: flex;
 flex-direction: column;
 gap: 0.25rem;
 }

 &__title {
 margin: 0;
 font-size: 0.875rem;
 font-weight: 600;
 }

 &__text {
 margin: 0;
 font-size: 0.8125rem;
 color: var(--inc-text-muted);
 }

 &--active {
 border-color: var(--bs-primary);
 background: linear-gradient(180deg, var(--bs-primary-bg-subtle), var(--inc-surface-primary));
 }

 &.is-drag-over,
 &:focus-visible {
 border-color: var(--bs-primary);
 background: linear-gradient(180deg, var(--bs-primary-bg-subtle), var(--inc-surface-primary));
 box-shadow: 0 0 0 3px rgba(var(--bs-primary-rgb), 0.14);
 outline: 0;
 }

 @media (max-width: 767.98px) {
 flex-direction: column;
 align-items: stretch;
 }
}

.inc-file-list {
 display: flex;
 flex-direction: column;
 gap: 0.75rem;
}

.inc-file-row {
 display: grid;
 grid-template-columns: minmax(0, 1fr) auto auto;
 gap: 1rem;
 align-items: center;
 padding: 0.875rem 1rem;
 border: 1px solid var(--inc-border-subtle);
 border-radius: $inc-radius-md;
 background: var(--inc-surface-primary);

 &__meta {
 display: flex;
 flex-direction: column;
 gap: 0.25rem;
 min-width: 0;
 }

 &__name {
 margin: 0;
 font-size: 0.875rem;
 font-weight: 600;
 }

 &__detail {
 margin: 0;
 font-size: 0.75rem;
 color: var(--inc-text-muted);
 }

 &__actions {
 display: flex;
 gap: 0.5rem;
 flex-wrap: wrap;
 justify-content: flex-end;
 }

 @media (max-width: 767.98px) {
 grid-template-columns: 1fr;
 align-items: stretch;

 &__actions {
 justify-content: flex-start;
 }
 }
}

.inc-drawer {
 display: flex;
 flex-direction: column;
 gap: 1rem;
 height: 100%;
 padding: 1.25rem;
 border-left: 1px solid var(--inc-border-subtle);
 background: var(--inc-surface-primary);
 box-shadow: -1rem 0 2rem rgba(var(--inc-surface-strong-rgb), 0.08);

 &__header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 gap: 1rem;
 padding-bottom: 1rem;
 border-bottom: 1px solid var(--inc-border-subtle);
 }

 &__body {
 display: flex;
 flex-direction: column;
 gap: 1rem;
 }

 &__footer {
 display: flex;
 flex-wrap: wrap;
 gap: 0.75rem;
 padding-top: 1rem;
 border-top: 1px solid var(--inc-border-subtle);
 margin-top: auto;
 }
}

.inc-toast-stack {
 display: flex;
 flex-direction: column;
 gap: 0.75rem;
}

.inc-toast-card {
 display: flex;
 align-items: flex-start;
 gap: 0.875rem;
 padding: 0.875rem 1rem;
 border: 1px solid var(--inc-border-subtle);
 border-radius: $inc-radius-md;
 background: var(--inc-surface-primary);
 box-shadow: 0 0.75rem 1.5rem rgba(var(--inc-surface-strong-rgb), 0.08);

 &__icon {
 width: 2rem;
 height: 2rem;
 border-radius: 0.625rem;
 display: inline-flex;
 align-items: center;
 justify-content: center;
 background: var(--bs-primary-bg-subtle);
 color: var(--bs-primary-text-emphasis);
 font-weight: 700;
 flex: 0 0 auto;
 }

 &__title {
 margin: 0 0 0.25rem;
 font-size: 0.875rem;
 font-weight: 600;
 }

 &__text {
 margin: 0;
 font-size: 0.8125rem;
 color: var(--inc-text-muted);
 }
}

