 focusMenuItem(menu, "previous");
 return;
 }

 if (event.key === "Home") {
 event.preventDefault();
 focusMenuItem(menu, "first");
 return;
 }

 if (event.key === "End") {
 event.preventDefault();
 focusMenuItem(menu, "last");
 return;
 }

 if (event.key === "Escape") {
 event.preventDefault();
